pub(super) fn banks(locale: &str) -> Option<&'static [&'static str]> {
    Some(match locale {
        "de_DE" => DE_DE_BANKS,
        "el_CY" => EL_CY_BANKS,
        "ka_GE" => KA_GE_BANKS,
        "kk_KZ" => KK_KZ_BANKS,
        "pl_PL" => PL_PL_BANKS,
        "pt_BR" => PT_BR_BANKS,
        "ru_RU" => RU_RU_BANKS,
        "th_TH" => TH_TH_BANKS,
        "uk_UA" => UK_UA_BANKS,
        "zh_CN" => ZH_CN_BANKS,
        _ => return None,
    })
}
